using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Http.Headers;
using System.Security.Cryptography;

namespace PaRuX.Server;

/// <summary>
/// SEC-F01. Per-launch bearer keys for the llama-server processes PaRuX starts on loopback.
///
/// A key is 256 random bits (base64url, 43 characters), generated by Core for every launch, so a restart
/// always rotates it. It exists only in this process's memory and in the child's environment block
/// (<c>LLAMA_API_KEY</c>, verified in llama-server --help): never in argv (visible to every user in the process
/// list), on disk, in the launch descriptor, or in a log. llama-server exempts <c>/health</c>, <c>/v1/models</c>
/// and the static web UI from the key; every other route, including /v1/chat/completions, /v1/embeddings,
/// /props and /slots, answers 401 without it.
///
/// Why <c>LLAMA_API_KEY</c> does not destabilise <see cref="TextLaunchDescriptor"/>: the descriptor hashes only
/// launch-relevant environment variables and drops the credential names (see
/// <c>TextLaunchDescriptor.IsLaunchRelevantEnvironment</c>), so the planned and the actual launch fingerprints
/// are the same whatever key a launch carries. Tests pin that.
/// </summary>
internal static class ManagedRuntimeCredentials
{
    /// <summary>llama-server's environment spelling of <c>--api-key</c>.</summary>
    internal const string KeyEnvironmentVariable = "LLAMA_API_KEY";

    private const int KeyBytes = 32;
    private const int MaximumRememberedKeys = 64;
    internal const string RedactionMarker = "[redacted-runtime-key]";

    private static readonly object Gate = new();
    private static readonly ConcurrentDictionary<int, string> KeysByPort = new();
    // Every key ever issued by this process (bounded), so output of a process that is still draining after its key was
    // retired is redacted as well. Held in memory only.
    private static readonly Queue<string> Remembered = new();
    private static int _textPort;

    /// <summary>A fresh 256-bit key, base64url without padding. It contains no comma, which llama-server would split on.</summary>
    internal static string NewKey()
    {
        string key = Convert.ToBase64String(RandomNumberGenerator.GetBytes(KeyBytes))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_');
        lock (Gate)
        {
            Remembered.Enqueue(key);
            while (Remembered.Count > MaximumRememberedKeys) Remembered.Dequeue();
        }
        return key;
    }

    /// <summary>
    /// Gives a launch its own key through the environment of the child and returns it for the caller's clients.
    /// Nothing is added to the argument list. A key or key-file the surrounding environment may already carry is replaced.
    /// </summary>
    internal static string ApplyTo(ProcessStartInfo start)
    {
        string key = NewKey();
        start.Environment.Remove("LLAMA_ARG_API_KEY_FILE");
        start.Environment.Remove("LLAMA_ARG_API_KEY");
        start.Environment[KeyEnvironmentVariable] = key;
        return key;
    }

    /// <summary>
    /// Keys the managed text runtime of this Core session: applies a fresh key to the child and publishes it for the
    /// loopback <paramref name="port"/> so every internal client reaches it. A previous text key is retired first.
    /// </summary>
    internal static void BeginTextLaunch(ProcessStartInfo start, int port)
    {
        string key = ApplyTo(start);
        lock (Gate)
        {
            if (_textPort > 0 && _textPort != port) KeysByPort.TryRemove(_textPort, out _);
            _textPort = port;
            KeysByPort[port] = key;
        }
    }

    /// <summary>Retires the managed text runtime key. Called with the launch identity: a stopped or failed runtime has no key.</summary>
    internal static void RetireText()
    {
        lock (Gate)
        {
            if (_textPort > 0) KeysByPort.TryRemove(_textPort, out _);
            _textPort = 0;
        }
    }

    internal static bool TryGetForPort(int port, out string key)
    {
        if (KeysByPort.TryGetValue(port, out string? value)) { key = value; return true; }
        key = string.Empty;
        return false;
    }

    /// <summary>Replaces every key this process has issued with a fixed marker. Null stays null.</summary>
    internal static string? Redact(string? text)
    {
        if (string.IsNullOrEmpty(text)) return text;
        string[] keys;
        lock (Gate) keys = Remembered.ToArray();
        foreach (string key in keys)
            if (text.Contains(key, StringComparison.Ordinal))
                text = text.Replace(key, RedactionMarker, StringComparison.Ordinal);
        return text;
    }

    /// <summary>A client for an isolated llama-server this caller launched: its own key is its default credential.</summary>
    internal static void Authorize(HttpClient client, string key) =>
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);

    /// <summary>Test seam: forget every published key and every remembered key.</summary>
    internal static void ResetForTests()
    {
        lock (Gate)
        {
            KeysByPort.Clear();
            Remembered.Clear();
            _textPort = 0;
        }
    }
}

/// <summary>
/// Adds the managed text runtime key to requests for its exact loopback port, replacing whatever Authorization the
/// request carried, so a forwarded caller token can never reach the runtime and a request for any other
/// host or port never carries the key. Wrapped around the attested handler: the key is written to the wire only after
/// the connection has been attested to the launched process.
/// </summary>
internal sealed class ManagedRuntimeKeyHandler : DelegatingHandler
{
    internal ManagedRuntimeKeyHandler(HttpMessageHandler inner) : base(inner) { }

    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        if (request.RequestUri is { IsAbsoluteUri: true } uri
            && uri.IsLoopback
            && ManagedRuntimeCredentials.TryGetForPort(uri.Port, out string key))
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", key);
        return base.SendAsync(request, cancellationToken);
    }
}
